Method.Implementation:
	set pResponse=##class(IHC.ITF.ITFCOMMON.DataStructure.OrderSuperset).%New()

	set dbObj = ##class(IHC.ITF.ITFCOMMON.Operation.CallTouchWorksStoredProcedures).%New(..Adapter)

	Set tSC = dbObj.GetExtractEncounterCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
  	set pResponse.ExtractEncounterCMS = $ZSTRIP(resp,"*C")
  	Set tSC = dbObj.GetExtractPatientCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractPatientCMS = $ZSTRIP(resp,"*C")

  	Set tSC = dbObj.GetExtractPersonCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractPersonCMS = $ZSTRIP(resp,"*C")

  	Set tSC = dbObj.GetExtractOrderItemCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractOrderItemCMS = $ZSTRIP(resp,"*C")

  	Set tSC = dbObj.GetExtractInsuranceCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractInsurance = $ZSTRIP(resp,"*C")

  	Set tSC = dbObj.GetExtractCase(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractCase = $ZSTRIP(resp,"*C")

  	Set tSC = dbObj.GetExtractOrderAdditionalInformationString(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractOrderAdditionalInformationString = $ZSTRIP(resp,"*C")

  	return tSC
